WITH valid AS (SELECT *, DATE_SUB(signup_date, 21) signup_date_minus_21d, COALESCE(segment, 'DIRECT') segment_clean FROM customers WHERE signup_date >= DATE '2024-04-06' AND segment IS NOT NULL AND LOWER(email) LIKE '%mma%'), matched_keys AS (SELECT city FROM valid EXCEPT DISTINCT SELECT city FROM customers WHERE country IN ('US', 'DE', 'JP')), reconciled AS (SELECT s.* FROM valid s INNER JOIN matched_keys k ON s.city = k.city), enriched AS (SELECT id, name, email, country, city, segment, signup_date, is_active, credit_limit, age, signup_date_minus_21d, segment_clean, SUM(credit_limit) OVER (PARTITION BY segment) segment_sum_credit_limit, ROUND(age / SUM(age) OVER (PARTITION BY city, country), 4) age_share, CORR(credit_limit, age) OVER (PARTITION BY city) corr_credit_limit_age, ROUND(age / SUM(age) OVER (PARTITION BY city), 4) age_share_2 FROM reconciled), enriched_customers AS (SELECT id, name, email, country, city, segment, signup_date, is_active, credit_limit, age, signup_date_minus_21d, segment_clean, segment_sum_credit_limit, age_share, corr_credit_limit_age, age_share_2, ROUND(segment_sum_credit_limit / SUM(segment_sum_credit_limit) OVER (PARTITION BY country), 4) segment_sum_credit_limit_share, RANK() OVER (ORDER BY credit_limit DESC) credit_limit_rank, PERCENT_RANK() OVER (ORDER BY age NULLS LAST) age_percent_rank, PERCENT_RANK() OVER (PARTITION BY country, city ORDER BY age_share DESC NULLS FIRST) age_share_percent_rank FROM enriched), scored AS (SELECT id, name, email, country, city, segment, signup_date, is_active, credit_limit, age, signup_date_minus_21d, segment_clean, segment_sum_credit_limit, age_share, corr_credit_limit_age, age_share_2, segment_sum_credit_limit_share, credit_limit_rank, age_percent_rank, age_share_percent_rank, DENSE_RANK() OVER w_ordered corr_credit_limit_age_dense_rank, COUNT(age_share_2) OVER (PARTITION BY city) city_count_age_share_2, CORR(age, credit_limit) OVER w_running corr_age_credit_limit, RANK() OVER (PARTITION BY country ORDER BY corr_credit_limit_age) corr_credit_limit_age_rank, PERCENT_RANK() OVER w_running_2 age_share_2_percent_rank FROM enriched_customers WINDOW w_ordered AS (ORDER BY corr_credit_limit_age DESC NULLS LAST), w_running AS (PARTITION BY segment), w_running_2 AS (PARTITION BY city, segment ORDER BY age_share_2 DESC NULLS LAST)), metrics AS (SELECT *, RANK() OVER (ORDER BY age DESC NULLS FIRST) age_rank, RANK() OVER (PARTITION BY segment, country ORDER BY city_count_age_share_2 NULLS LAST) city_count_age_share_2_rank, MAX(segment_sum_credit_limit_share) OVER (PARTITION BY city) city_max_segment_sum_credit_limit_share, AVG(age_percent_rank) OVER (PARTITION BY country) country_avg_age_percent_rank FROM scored), cleaned AS (SELECT *, city_count_age_share_2 - corr_age_credit_limit city_count_age_share_2_minus_corr_age_credit_limit FROM metrics WHERE signup_date >= DATE '2023-08-21' AND city IS NOT NULL), by_type AS (SELECT * FROM (SELECT country, segment, corr_credit_limit_age_rank FROM cleaned) src PIVOT (SUM(corr_credit_limit_age_rank) AS amount FOR segment IN ('SMB' AS smb, 'Consumer' AS consumer, 'Corporate' AS corporate))) SELECT country, smb, corporate FROM by_type ORDER BY country DESC;
